/// A packet as the feedback link sees it.
#[derive(Clone, Copy, Debug)]
struct Pending {
    depart_ms: f64,
    lane: Lane,
    kind: u8,
    len: usize,
}

/// The closed loop of seam S15: the simulated link, fed every packet the
/// scored client is sent in the order the final run sorts them (lab packets
/// by tick phase, recorded ones by queue time, the lab's first at equal
/// times), and the production rate controller reading it.
struct Feedback {
    sim: LinkSim,
    pub controller: RateController,
    stale_ms: f64,
    pass: Vec<Pending>,
    pass_next: usize,
    lab: std::collections::VecDeque<Pending>,
    last_admit_ms: f64,
    origin_ms: Option<f64>,
    /// Samples read so far (for a stale view).
    samples: std::collections::VecDeque<(f64, LinkSample)>,
    buffered: Vec<u64>,
    send_interval_s: f64,
    ceiling_bytes: usize,
    trace: Vec<RateTraceRow>,
}

impl Feedback {
    fn new(adapt: &RateAdapt, passed: &[Outgoing], send_interval_s: f64, ceiling_bytes: usize) -> Self {
        let mut pass: Vec<Pending> = passed
            .iter()
            .map(|p| Pending { depart_ms: p.depart_ms, lane: p.lane, kind: p.kind, len: p.bytes.len() })
            .collect();
        // Stable: equal queue times keep tape order, as their sequence
        // numbers do in the final sort.
        pass.sort_by(|a, b| a.depart_ms.total_cmp(&b.depart_ms));
        Self {
            sim: LinkSim::new(&adapt.profile, adapt.seed),
            controller: RateController::new(adapt.config),
            stale_ms: adapt.stale_ms,
            pass,
            pass_next: 0,
            lab: Default::default(),
            last_admit_ms: f64::MIN,
            origin_ms: None,
            samples: Default::default(),
            buffered: Vec::new(),
            send_interval_s,
            ceiling_bytes,
            trace: Vec::new(),
        }
    }

    fn push_lab(&mut self, depart_ms: f64, bytes: &[u8]) {
        let kind = bytes[0];
        self.lab.push_back(Pending { depart_ms, lane: Lane::of_kind(kind), kind, len: bytes.len() });
    }

    /// Admit everything that departs before `at_ms` (lab packets at `at_ms`
    /// too: they precede this send in the final order).
    fn feed_until(&mut self, at_ms: f64) {
        loop {
            let lab = self.lab.front().filter(|p| p.depart_ms <= at_ms).copied();
            let pass = self.pass.get(self.pass_next).filter(|p| p.depart_ms < at_ms).copied();
            let next = match (lab, pass) {
                (Some(l), Some(p)) if l.depart_ms <= p.depart_ms => {
                    self.lab.pop_front();
                    l
                }
                (Some(_), Some(p)) | (None, Some(p)) => {
                    self.pass_next += 1;
                    p
                }
                (Some(l), None) => {
                    self.lab.pop_front();
                    l
                }
                (None, None) => break,
            };
            // Recorded tick phases can run a hair behind the previous tick's;
            // the link admits in time order.
            let depart = next.depart_ms.max(self.last_admit_ms);
            self.sim.admit(depart, next.lane, next.kind, next.len);
            self.last_admit_ms = depart;
        }
    }

    fn plan(&mut self, at_ms: f64, tick: u32) -> SendPlan {
        self.feed_until(at_ms);
        let at_ms = at_ms.max(self.last_admit_ms);
        let origin = *self.origin_ms.get_or_insert(at_ms - 1000.0);
        let signals = self.sim.signals(at_ms);
        let sample = LinkSample {
            at_us: ((at_ms - origin) * 1000.0).max(0.0) as u64,
            datagram_buffered_bytes: signals.datagram_buffered_bytes,
            wire_bytes: signals.wire_bytes,
            sent_packets: signals.sent_packets,
            lost_packets: signals.lost_packets,
            lost_bytes: signals.lost_bytes,
            rtt_us: (signals.rtt_ms * 1000.0) as u64,
            submitted_bytes: signals.submitted_bytes,
            reliable_submitted_bytes: signals.reliable_submitted_bytes,
        };
        self.samples.push_back((at_ms, sample));
        // A stale view (sensitivity probe): the newest sample at least
        // `stale_ms` old, stamped when it was read.
        let seen = if self.stale_ms > 0.0 {
            while self.samples.len() > 1 && self.samples[1].0 <= at_ms - self.stale_ms {
                self.samples.pop_front();
            }
            self.samples[0].1
        } else {
            self.samples.clear();
            sample
        };
        self.buffered.push(sample.datagram_buffered_bytes);
        let plan = self.controller.plan(seen, self.send_interval_s, self.ceiling_bytes);
        self.trace.push(RateTraceRow {
            t_ms: at_ms,
            tick,
            limited: self.controller.state() == crate::link_rate::RateState::Limited,
            buffered_bytes: sample.datagram_buffered_bytes,
            capacity_kbit_s: self.controller.capacity_bytes_per_s() * 8.0 / 1000.0,
            other_kbit_s: self.controller.other_rate_bytes_per_s() * 8.0 / 1000.0,
            city_rate_kbit_s: self.controller.city_rate_bytes_per_s() * 8.0 / 1000.0,
            reliable_backlog_bytes: self.controller.reliable_backlog_bytes(),
            stream_backlog_bytes: self.sim.stream_backlog_bytes(),
            allowance_bytes: plan.allowance(),
            used_bytes: 0,
        });
        plan
    }

    /// What the send queued, back to the controller.
    fn sent(&mut self, bytes: usize, plan: SendPlan) {
        self.controller.sent(bytes, plan);
        if let Some(row) = self.trace.last_mut() {
            row.used_bytes = bytes;
        }
    }

    /// Topology copies on a send with no plan (no records) or a skipped one.
    fn sent_topology(&mut self, bytes: usize, planned: bool) {
        self.controller.sent_topology(bytes);
        if planned {
            if let Some(row) = self.trace.last_mut() {
                row.used_bytes = bytes;
            }
        }
    }

    fn into_stats(mut self) -> (CityRateStats, Vec<RateTraceRow>) {
        let totals = self.controller.totals();
        self.buffered.sort_unstable();
        let pick = |q: f64| -> u64 {
            if self.buffered.is_empty() {
                0
            } else {
                self.buffered[((self.buffered.len() - 1) as f64 * q).round() as usize]
            }
        };
        let stats = CityRateStats {
            sends_full: totals.sends_full,
            sends_limited: totals.sends_limited,
            sends_skipped: totals.sends_skipped,
            entered_limited: totals.entered_limited,
            released: totals.released,
            policer_cuts: totals.policer_cuts,
            mean_limited_allowance_bytes: if totals.sends_limited == 0 {
                0.0
            } else {
                totals.limited_allowance_bytes as f64 / totals.sends_limited as f64
            },
            buffered_p50_bytes: pick(0.5),
            buffered_p99_bytes: pick(0.99),
            buffered_max_bytes: self.buffered.last().copied().unwrap_or(0),
            final_capacity_kbit_s: self.controller.capacity_bytes_per_s() * 8.0 / 1000.0,
        };
        (stats, self.trace)
    }
}

pub struct Stream {
    pub packets: Vec<Outgoing>,
    pub stats: StreamStats,
    pub join: Join,
    /// The rate controller's per-send decisions (closed loop only).
    pub rate_trace: Vec<RateTraceRow>,
}

pub fn build(bundle: &Bundle, config: &StreamConfig) -> std::io::Result<Stream> {
    let join = join(bundle);
    let clock = Clock::new(bundle, config.pace);
    let player = bundle.player;
    let mut stats = StreamStats {
        first_tick: bundle.first_tick(),
        last_tick: bundle.last_tick(),
        ..Default::default()
    };
    let mut emit = Emitter { out: Vec::new(), seq: 0, ordinals: HashMap::new() };

    // ── snapshot stream ──────────────────────────────────────────────────
    let baseline = bundle.snapshot_baseline.as_ref();
    let live_strict = baseline.map(|b| b.strict_snapshot_datagrams).unwrap_or_else(|| {
        !bundle.tape.packets.iter().any(|p| p.kind() == PKT_SNAPSHOT)
    });
    let live_snapshot_hz = baseline
        .map(|b| b.snapshot_hz)
        .or_else(|| bundle.tape.header["session"]["snapshotHz"].as_u64().map(|hz| hz as u32))
        .unwrap_or(bundle.sim_hz)
        .max(1);
    let snapshot_interval = config
        .snapshot_interval_ticks
        .unwrap_or((bundle.sim_hz / live_snapshot_hz).max(1))
        .max(1);
    stats.snapshot_interval_ticks = snapshot_interval;
    stats.strict_snapshots = live_strict;
    stats.snapshot_inputs = if bundle.snapshot_inputs.is_some() {
        "recorded (snapshot-inputs.jsonl)"
    } else {
        "recovered: acks from the client tape, no support"
    }
    .into();
    stats.snapshot_interest_start = if baseline.map_or(false, |b| b.interest.contains_key(&player)) {
        "recorded (snapshot-baseline.json)"
    } else {
        "empty"
    }
    .into();
    let snapshot_config = SnapshotConfig {
        compact_self: config
            .snapshot_compact_self
            .unwrap_or_else(|| baseline.map_or(false, |b| b.compact_self)),
        removals: config.snapshot_removals.unwrap_or_else(|| baseline.map_or(false, |b| b.removals)),
        ..config.snapshot
    };
    stats.snapshot_format = format!(
        "compact_self {} removals {}",
        snapshot_config.compact_self, snapshot_config.removals
    );
    let mut interest: RecipientInterest = baseline
        .and_then(|b| b.interest.get(&player).cloned())
        .unwrap_or_default();
    let acks = if bundle.snapshot_inputs.is_none() { recorded_acks(bundle) } else { BTreeMap::new() };
    let mut last_ack = 0u16;
    let baseline_meta: Option<HashMap<u32, BodyMeta>> =
        baseline.map(|b| b.body_meta.iter().map(|(k, v)| (*k, *v)).collect());
    let mut snapshots: BTreeMap<u32, Vec<u8>> = BTreeMap::new();
    for truth in &bundle.world {
        let tick = truth.tick;
        if tick % snapshot_interval != 0 {
            continue;
        }
        let inputs = bundle.snapshot_inputs.as_ref().and_then(|map| map.get(&tick));
        if bundle.snapshot_inputs.is_some() && inputs.is_none() {
            // The live match took no snapshot this tick (or its record was
            // dropped); with a changed interval the lab still must.
            if config.snapshot_interval_ticks.is_none() {
                continue;
            }
        }
        let meleeing = |id: u32| inputs.map_or(false, |i| i.meleeing.contains(&id));
        let players: Vec<_> = truth
            .players
            .iter()
            .map(|p| {
                let flags = if meleeing(p.id) { p.flags | FLAG_MELEEING } else { p.flags };
                (
                    p.id,
                    p.position,
                    make_net_player_state(p.id, p.position, p.velocity, p.yaw, p.pitch, p.hp, flags, 0.0),
                )
            })
            .collect();
        let bodies: Vec<_> = truth
            .bodies
            .iter()
            .map(|b| {
                (
                    b.id,
                    b.position,
                    b.rotation,
                    make_net_dynamic_body_state(
                        b.id,
                        b.position,
                        b.rotation,
                        b.half_extents,
                        b.velocity,
                        b.angular_velocity,
                        b.shape,
                    ),
                )
            })
            .collect();
        let vehicles: Vec<_> =
            truth.vehicles.iter().map(|v| (v.id, v.position, vehicle_wire_state(v))).collect();
        let player_handles: HashMap<u32, u8> = truth
            .players
            .iter()
            .filter(|p| p.handle != 0)
            .map(|p| (p.id, p.handle))
            .collect();
        let vehicle_handles: HashMap<u32, u8> = truth
            .vehicles
            .iter()
            .filter(|v| v.handle != 0)
            .map(|v| (v.id, v.handle))
            .collect();
        let body_meta: HashMap<u32, BodyMeta> = match &baseline_meta {
            Some(meta) => meta.clone(),
            None => truth
                .bodies
                .iter()
                .filter(|b| b.handle != 0)
                .map(|b| {
                    (b.id, BodyMeta { handle: b.handle, shape_type: b.shape, half_extents_m: b.half_extents })
                })
                .collect(),
        };
        let world = SnapshotWorld {
            server_tick: tick,
            server_time_us: u64::from(tick) * (1_000_000 / u64::from(bundle.sim_hz)),
            server_wall_us: wall_stamp(bundle, tick, inputs, config.pace),
            players: &players,
            bodies: &bodies,
            vehicles: &vehicles,
            player_handles: &player_handles,
            vehicle_handles: &vehicle_handles,
            body_meta: &body_meta,
        };
        let recipient = match inputs.and_then(|i| i.recipients.iter().find(|r| r.id == player)) {
            Some(recorded) => *recorded,
            None => {
                if let Some((_, ack)) = acks.range(..=tick).next_back() {
                    last_ack = *ack;
                }
                RecipientInput { id: player, ack_input_seq: last_ack, support: None }
            }
        };
        let Some((packet, selection)) = snapshot_builder::build_recipient_snapshot(
            &world,
            &recipient,
            &mut interest,
            live_strict,
            &snapshot_config,
        ) else {
            continue;
        };
        let bytes = encode_server_packet(&packet);
        for (name, value) in [
            ("players_aoi", selection.players_aoi),
            ("players_sent", selection.players_sent),
            ("players_budget", selection.players_budget),
            ("vehicles_aoi", selection.vehicles_aoi),
            ("vehicles_sent", selection.vehicles_sent),
            ("vehicles_budget", selection.vehicles_budget),
            ("bodies_aoi", selection.bodies_aoi),
            ("bodies_hot", selection.bodies_hot),
            ("bodies_sent", selection.bodies_sent),
            ("bodies_budget", selection.bodies_budget),
            ("bodies_unchanged", selection.bodies_unchanged),
            ("out_of_range", selection.out_of_range),
            ("bytes", bytes.len() as u32),
        ] {
            *stats.snapshot_selection.entry(name.into()).or_default() += u64::from(value);
        }
        stats.snapshot_ticks += 1;
        snapshots.insert(tick, bytes);
    }

    // ── the windows the lab owns ─────────────────────────────────────────
    let city_first = match &bundle.city {
        Some(city) => {
            let mut reader =
                TapeReader::open(&city.dir.join(vibe_land_destruction::netlab::capture::TAPE_FILE))?;
            reader.next_tick()?.map(|entry| entry.tick)
        }
        None => None,
    };
    let city_first_tick = city_first.unwrap_or(u32::MAX);
    // The lab owns the snapshot stream over the whole captured window (not
    // just the ticks it chose to send: a slower cadence must not let the
    // live snapshots at its edges leak through).
    let snapshot_window = if snapshots.is_empty() {
        (u32::MAX, 0)
    } else {
        (bundle.first_tick(), bundle.last_tick())
    };
    let lab_covers = |tick: u32, kind: u8| -> bool {
        if is_snapshot_kind(kind) {
            tick >= snapshot_window.0 && tick <= snapshot_window.1
        } else if kind == PKT_CITY_STRUCTURE_BOOTSTRAP {
            false
        } else if is_city_encoder_kind(kind) {
            tick >= city_first_tick
        } else {
            false
        }
    };

    // ── recorded packets around the lab's (sequence numbers assigned after
    //    the lab's, below, so the final order is unchanged) ─────────────────
    let mut passed: Vec<Outgoing> = Vec::new();
    for (index, packet) in bundle.tape.packets.iter().enumerate() {
        if packet.is_prelude() || packet.base_channel() == CHANNEL_RTT {
            continue;
        }
        let kind = packet.kind();
        match join.tape_to_record.get(&index) {
            Some(&record_index) => {
                let record = &bundle.sendlog[record_index];
                if lab_covers(record.tick, kind) {
                    continue;
                }
                if kind == PKT_CITY_STRUCTURE_BOOTSTRAP {
                    if !config.recorded_repairs {
                        stats.city_structure_bootstraps_withheld += 1;
                        continue;
                    }
                    stats.city_structure_bootstraps_passed_through += 1;
                }
                let queued = if record.queued_us == crate::send_log::QUEUED_BEFORE_CAPTURE {
                    record.sent_us
                } else {
                    record.queued_us
                };
                let depart = clock.retime(record.tick, bundle.server_to_tape_ms(queued));
                *stats.passthrough_by_kind.entry(kind).or_default() += 1;
                passed.push(Outgoing {
                    depart_ms: depart,
                    seq: 0,
                    tick: record.tick,
                    lane: Lane::of_kind(kind),
                    kind,
                    bytes: packet.bytes.clone(),
                    origin: Origin::Pass,
                    tape_index: Some(index),
                    live_record: Some(record_index),
                    ordinal: 0,
                });
            }
            None => {
                // Before the capture: only what precedes the lab's windows.
                let lane = if packet.base_channel() == CHANNEL_WT_DATAGRAM {
                    Lane::Datagram
                } else {
                    Lane::Reliable
                };
                let latency = join.median_latency_ms.get(&lane).copied().unwrap_or(0.5);
                *stats.prepass_by_kind.entry(kind).or_default() += 1;
                passed.push(Outgoing {
                    depart_ms: packet.t_ms - latency,
                    seq: 0,
                    tick: 0,
                    lane,
                    kind,
                    bytes: packet.bytes.clone(),
                    origin: Origin::PrePass,
                    tape_index: Some(index),
                    live_record: None,
                    ordinal: 0,
                });
            }
        }
    }

    // ── city stream ──────────────────────────────────────────────────────
    let mut rate_trace: Vec<RateTraceRow> = Vec::new();
    let mut city_ticks: BTreeMap<u32, (Vec<Vec<u8>>, Vec<Vec<u8>>)> = BTreeMap::new();
    let mut city_after_tick: BTreeMap<u32, Vec<Vec<u8>>> = BTreeMap::new();
    if let Some(city) = &bundle.city {
        let mut reader = TapeReader::open(&city.dir.join(vibe_land_destruction::netlab::capture::TAPE_FILE))?;
        let mut encoder = match city.checkpoint.clone() {
            Some(mut checkpoint) => {
                config.city.apply(&mut checkpoint.config);
                stats.city_encoder_start = "checkpoint (exact)".into();
                ChunkStreamEncoder::from_checkpoint(&city.manifest, checkpoint)
                    .map_err(std::io::Error::other)?
            }
            None => {
                // Mirrors CityRuntime::from_parts; used only for captures
                // taken before the checkpoint existed.
                let mut encoder_config = EncoderConfig::validated(reader.hz);
                encoder_config.send_interval_ticks = (reader.hz
                    / u32::from(vibe_land_shared::constants::CITY_CHUNK_STREAM_HZ))
                .max(1);
                encoder_config.client_ceiling_bytes =
                    usize::from(vibe_land_shared::constants::CITY_CLIENT_CEILING_BYTES_PER_SEND);
                encoder_config.interest.proximity_meters = 120.0;
                config.city.apply(&mut encoder_config);
                stats.city_encoder_start = "fresh (no checkpoint; approximate)".into();
                let mut encoder = ChunkStreamEncoder::new(&city.manifest, encoder_config);
                encoder.add_client(u64::from(player));
                encoder
            }
        };
        let encoder_config = encoder.config();
        stats.city_send_interval_ticks = encoder_config.send_interval_ticks;
        stats.city_ceiling_bytes = encoder_config.client_ceiling_bytes;
        // Closed loop (seam S15): the link model, fed every packet as it
        // departs, read by the production controller at each of the scored
        // client's sends.
        let mut feedback = config.rate_adapt.as_ref().map(|adapt| {
            Feedback::new(
                adapt,
                &passed,
                f64::from(encoder_config.send_interval_ticks.max(1)) / f64::from(encoder_config.sim_hz.max(1)),
                encoder_config.client_ceiling_bytes,
            )
        });
        let mut snapshots_fed_from = 0u32;

        // Cameras per send tick, in the live call order; and every player's
        // most recent camera for sends the live match never made.
        let mut cameras_at: BTreeMap<u32, Vec<(u32, Camera)>> = BTreeMap::new();
        for sample in &city.cameras {
            cameras_at.entry(sample.tick).or_default().push((
                sample.player,
                Camera {
                    eye: glam::Vec3::from_array(sample.eye),
                    direction: glam::Vec3::from_array(sample.dir),
                    fov_degrees: sample.fov,
                },
            ));
        }
        let mut latest_camera: BTreeMap<u32, Camera> = BTreeMap::new();
        let mut events_at: BTreeMap<u32, Vec<&serde_json::Value>> = BTreeMap::new();
        for event in &city.events {
            if let Some(tick) = event["tick"].as_u64() {
                events_at.entry(tick as u32).or_default().push(event);
            }
        }
        // Bootstraps the live server queued for this client, by tick: joins,
        // resyncs the client asked for, repairs. Replayed open-loop.
        let mut bootstraps_at: BTreeMap<u32, u32> = BTreeMap::new();
        for ((tick, kind), records) in &join.records_by_tick_kind {
            if *kind == PKT_CITY_BOOTSTRAP {
                *bootstraps_at.entry(*tick).or_default() += records.len() as u32;
            }
        }
        let mut first_city_tick = None;
        while let Some(entry) = reader.next_tick()? {
            let tick = entry.tick;
            first_city_tick.get_or_insert(tick);
            let (_, city_at, snapshot_at, end_at) = clock.phases(tick);
            if let Some(feedback) = feedback.as_mut() {
                // Every snapshot of an earlier tick is on its way.
                for (snap_tick, bytes) in snapshots.range(snapshots_fed_from..tick) {
                    feedback.push_lab(clock.phases(*snap_tick).2, bytes);
                }
                snapshots_fed_from = snapshots_fed_from.max(tick);
            }
            encoder.ingest_tick(tick, &entry.snapshots, &entry.output, &entry.output.wakes);
            let mut reliable = encoder.take_topology_messages();
            if let Some(baselines) = encoder.maybe_emit_baseline(tick) {
                reliable.extend(baselines);
            }
            if tick % TOPO_HASH_INTERVAL_TICKS == 0 {
                reliable.push(encoder.topology_hash_message());
            }
            if let Some(feedback) = feedback.as_mut() {
                for bytes in &reliable {
                    feedback.push_lab(city_at, bytes);
                }
            }
            if let Some(list) = cameras_at.get(&tick) {
                for (id, camera) in list {
                    latest_camera.insert(*id, *camera);
                }
            }
            let mut datagrams = Vec::new();
            let interval = encoder_config.send_interval_ticks.max(1);
            if tick % interval == 0 && !latest_camera.is_empty() {
                // Live order where the live match sent this tick; otherwise
                // the players' latest cameras in id order.
                let order: Vec<(u32, Camera)> = match cameras_at.get(&tick) {
                    Some(list) if config.city.send_hz.is_none() => list.clone(),
                    _ => latest_camera.iter().map(|(id, c)| (*id, *c)).collect(),
                };
                let shared = encoder.encode_send(tick);
                let has_records = !shared.records.is_empty();
                for (id, camera) in order {
                    let client = u64::from(id);
                    // A send with no records still carries the client's
                    // pending topology copies, ahead of any records
                    // (`add_topology_copies`), as `MatchState::tick_city` does.
                    if !has_records && !encoder.has_topology_copies(client) {
                        continue;
                    }
                    let mut packets = Vec::new();
                    if id != player {
                        encoder.add_topology_copies(client, tick, &mut packets);
                        if has_records {
                            encoder.client_datagrams(client, camera, &shared);
                        }
                        continue;
                    }
                    // As `MatchState::city_datagrams_for` does: the plan
                    // first, then the topology copies, then the records under
                    // what the copies left of the allowance (or none), then
                    // what it queued goes back to the controller.
                    let plan = match (has_records, feedback.as_mut()) {
                        (true, Some(feedback)) => Some(feedback.plan(city_at, tick)),
                        (true, None) => Some(SendPlan::Full),
                        (false, _) => None,
                    };
                    let copies = encoder.add_topology_copies(client, tick, &mut packets);
                    if copies > 0 {
                        *stats.city_selection.entry("topology_copy_bytes".into()).or_default() += copies as u64;
                    }
                    match plan {
                        Some(plan) if plan != SendPlan::Skip => {
                            let records = encoder.client_datagrams_within(
                                client,
                                camera,
                                &shared,
                                plan.after_topology(copies).allowance(),
                            );
                            packets.extend(records);
                            let summary = encoder.last_client_selection();
                            if let Some(feedback) = feedback.as_mut() {
                                let bytes: usize = packets.iter().map(Vec::len).sum();
                                feedback.sent(bytes, plan);
                            }
                            for (name, value) in [
                                ("candidates", summary.candidates),
                                ("eval_cap", summary.eval_cap),
                                ("rest_stride", summary.rest_stride),
                                ("rest_unchanged", summary.rest_unchanged),
                                ("not_relevant", summary.not_relevant),
                                ("not_newsworthy", summary.not_newsworthy),
                                ("ceiling", summary.ceiling),
                                ("sent", summary.sent),
                                ("allowance_bytes", summary.allowance_bytes),
                                ("used_bytes", summary.used_bytes),
                            ] {
                                *stats.city_selection.entry(name.into()).or_default() += u64::from(value);
                            }
                        }
                        skipped => {
                            if skipped.is_some() {
                                *stats.city_selection.entry("rate_skipped_sends".into()).or_default() += 1;
                            }
                            if let Some(feedback) = feedback.as_mut() {
                                feedback.sent_topology(copies, skipped.is_some());
                            }
                        }
                    }
                    datagrams = packets;
                }
            }
            if let Some(feedback) = feedback.as_mut() {
                for bytes in &datagrams {
                    feedback.push_lab(city_at, bytes);
                }
                if let Some(bytes) = snapshots.get(&tick) {
                    feedback.push_lab(snapshot_at, bytes);
                }
                snapshots_fed_from = snapshots_fed_from.max(tick + 1);
            }
            city_ticks.insert(tick, (reliable, datagrams));
            // Between this tick and the next: joins and leaves (other
            // players, for their encoder state), and this client's
            // bootstraps where the live server sent them.
            for event in events_at.get(&tick).into_iter().flatten() {
                let Some(id) = event["player"].as_u64().map(|id| id as u32) else {
                    continue;
                };
                match event["kind"].as_str() {
                    Some("join") if id != player => encoder.add_client(u64::from(id)),
                    Some("join") => encoder.add_client(u64::from(id)),
                    Some("leave") => encoder.remove_client(u64::from(id)),
                    _ => {}
                }
            }
            if let Some(&count) = bootstraps_at.get(&tick) {
                let list = city_after_tick.entry(tick).or_default();
                for _ in 0..count {
                    list.push(encoder.bootstrap_message(tick));
                    // As the server does after a resync or repair bootstrap
                    // (a no-op for captures made before the reference lag).
                    encoder.note_client_bootstrap(u64::from(player));
                    stats.city_bootstraps += 1;
                }
                if let Some(feedback) = feedback.as_mut() {
                    for bytes in list.iter() {
                        feedback.push_lab(end_at, bytes);
                    }
                }
            }
        }
        stats.city_first_tick = first_city_tick;
        if let Some((rate, trace)) = feedback.map(Feedback::into_stats) {
            stats.city_rate = Some(rate);
            rate_trace = trace;
        }
    }

    // ── assemble: lab packets in tick phase order, recorded packets around ─
    let mut ticks: Vec<u32> = snapshots.keys().chain(city_ticks.keys()).chain(city_after_tick.keys()).copied().collect();
    ticks.sort_unstable();
    ticks.dedup();
    for tick in ticks {
        let (_, city_at, snapshot_at, end) = clock.phases(tick);
        if let Some((reliable, datagrams)) = city_ticks.remove(&tick) {
            for bytes in reliable {
                emit.lab(city_at, tick, bytes, &join);
            }
            for bytes in datagrams {
                emit.lab(city_at, tick, bytes, &join);
            }
        }
        if let Some(bytes) = snapshots.remove(&tick) {
            emit.lab(snapshot_at, tick, bytes, &join);
        }
        for bytes in city_after_tick.remove(&tick).into_iter().flatten() {
            emit.lab(end, tick, bytes, &join);
        }
    }
    for packet in &emit.out {
        *stats.lab_by_kind.entry(packet.kind).or_default() += 1;
    }
    for mut packet in passed {
        packet.seq = emit.seq;
        emit.seq += 1;
        emit.out.push(packet);
    }
    let mut packets = emit.out;
    packets.sort_by(|a, b| a.depart_ms.total_cmp(&b.depart_ms).then(a.seq.cmp(&b.seq)));
    Ok(Stream { packets, stats, join, rate_trace })
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::protocol::{cms_to_mps, mm_to_meters, snorm16_to_f32};
    use crate::session_capture::VehicleTruth;

    /// The capture writes vehicles as floats converted from wire units; the
    /// lab must get the identical wire state back or every vehicle record
    /// differs by a unit.
    #[test]
    fn vehicle_truth_inverts_to_the_wire_state() {
        let mut rng = 0x1234_5678u32;
        let mut next = |span: i32| {
            rng ^= rng << 13;
            rng ^= rng >> 17;
            rng ^= rng << 5;
            (rng % (2 * span as u32 + 1)) as i32 - span
        };
        for _ in 0..20_000 {
            let wire = NetVehicleState {
                id: 7,
                vehicle_type: 1,
                flags: 2,
                driver_id: 3,
                px_mm: next(900_000),
                py_mm: next(90_000),
                pz_mm: next(900_000),
                qx_snorm: next(32767) as i16,
                qy_snorm: next(32767) as i16,
                qz_snorm: next(32767) as i16,
                qw_snorm: next(32767) as i16,
                vx_cms: next(32767) as i16,
                vy_cms: next(32767) as i16,
                vz_cms: next(32767) as i16,
                wx_mrads: next(32767) as i16,
                wy_mrads: next(32767) as i16,
                wz_mrads: next(32767) as i16,
                wheel_data: [0; 4],
            };
            // Exactly what session_match.rs::collect_world_truth writes.
            let truth = VehicleTruth {
                id: wire.id,
                handle: 1,
                vehicle_type: wire.vehicle_type,
                flags: wire.flags,
                driver: wire.driver_id,
                position: [mm_to_meters(wire.px_mm), mm_to_meters(wire.py_mm), mm_to_meters(wire.pz_mm)],
                rotation: [
                    snorm16_to_f32(wire.qx_snorm),
                    snorm16_to_f32(wire.qy_snorm),
                    snorm16_to_f32(wire.qz_snorm),
                    snorm16_to_f32(wire.qw_snorm),
                ],
                velocity: [cms_to_mps(wire.vx_cms), cms_to_mps(wire.vy_cms), cms_to_mps(wire.vz_cms)],
                angular_velocity: [
                    wire.wx_mrads as f32 / 1000.0,
                    wire.wy_mrads as f32 / 1000.0,
                    wire.wz_mrads as f32 / 1000.0,
                ],
            };
            let back = vehicle_wire_state(&truth);
            assert_eq!(
                (back.px_mm, back.py_mm, back.pz_mm, back.qx_snorm, back.qy_snorm, back.qz_snorm, back.qw_snorm),
                (wire.px_mm, wire.py_mm, wire.pz_mm, wire.qx_snorm, wire.qy_snorm, wire.qz_snorm, wire.qw_snorm)
            );
            assert_eq!(
                (back.vx_cms, back.vy_cms, back.vz_cms, back.wx_mrads, back.wy_mrads, back.wz_mrads),
                (wire.vx_cms, wire.vy_cms, wire.vz_cms, wire.wx_mrads, wire.wy_mrads, wire.wz_mrads)
            );
        }
    }
}
